"use client";

import { useState, type FormEvent } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import Link from "next/link";
import { createClient } from "@/lib/supabase/client";

export default function LoginPage() {
  const router = useRouter();
  const params = useSearchParams();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(
    params.get("error") === "not-an-advisor"
      ? "That account isn't registered as an advisor."
      : null,
  );
  const [loading, setLoading] = useState(false);

  async function onSubmit(e: FormEvent) {
    e.preventDefault();
    setError(null);
    setLoading(true);
    const supabase = createClient();
    const { error } = await supabase.auth.signInWithPassword({
      email,
      password,
    });
    if (error) {
      setLoading(false);
      setError(error.message);
      return;
    }
    router.push(params.get("next") ?? "/dashboard");
    router.refresh();
  }

  return (
    /* No ruled ground here: a centred form floating on ruled paper reads as
       an accident. The ledger begins once you're inside it. */
    <main className="min-h-dvh grid lg:grid-cols-2">
      <div className="flex items-center justify-center px-6 py-16">
        <div className="w-full max-w-sm">
          <Link
            href="/"
            className="inline-flex items-baseline gap-2 mb-10 rounded-sm"
          >
            <span className="font-sans font-bold text-base tracking-tight">
              Vizor
            </span>
            <span className="text-[10px] uppercase tracking-[0.14em] text-ink-faint">
              Advisor
            </span>
          </Link>

          <h1 className="font-serif text-2xl">Sign in</h1>
          <p className="text-sm text-ink-soft mt-1 mb-7">
            Your advising caseload, one ledger.
          </p>

          <form onSubmit={onSubmit} noValidate className="space-y-4">
            <Field
              id="email"
              label="Email"
              type="email"
              autoComplete="email"
              value={email}
              onChange={setEmail}
              placeholder="schen@asu.edu"
              invalid={Boolean(error)}
            />
            <Field
              id="password"
              label="Password"
              type="password"
              autoComplete="current-password"
              value={password}
              onChange={setPassword}
              invalid={Boolean(error)}
            />

            {error && (
              <p
                className="text-sm text-maroon-ink border-l-2 border-maroon pl-3 py-0.5"
                role="alert"
              >
                {error}
              </p>
            )}

            <button
              type="submit"
              disabled={loading || !email || !password}
              className="w-full rounded-md bg-ink text-paper-raised px-4 py-2.5 text-sm font-medium transition-colors duration-150 ease-out hover:bg-ink/90 active:scale-[0.99] disabled:opacity-40 disabled:pointer-events-none"
            >
              {loading ? "Signing in…" : "Sign in"}
            </button>
          </form>
        </div>
      </div>

      {/* The ruled ground appears here as a preview of the surface you're
          signing in to, rather than as wallpaper behind the form. */}
      <aside className="ruled hidden lg:flex items-center justify-center border-l border-rule px-10">
        <blockquote className="max-w-sm">
          <p className="font-serif text-2xl leading-snug text-balance">
            Every ticket arrives{" "}
            <span className="italic">already understood.</span>
          </p>
          <p className="text-sm text-ink-soft mt-3 leading-relaxed">
            Session context, escalation reason, and the student&rsquo;s DARS
            audit are attached before you open it.
          </p>
        </blockquote>
      </aside>
    </main>
  );
}

function Field({
  id,
  label,
  type,
  autoComplete,
  value,
  onChange,
  placeholder,
  invalid,
}: {
  id: string;
  label: string;
  type: string;
  autoComplete: string;
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
  invalid?: boolean;
}) {
  return (
    <div>
      <label
        htmlFor={id}
        className="block text-[11px] font-semibold uppercase tracking-[0.08em] text-ink-faint mb-1.5"
      >
        {label}
      </label>
      <input
        id={id}
        type={type}
        autoComplete={autoComplete}
        required
        aria-invalid={invalid}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className={`w-full rounded-md border bg-paper-raised px-3 py-2.5 text-sm transition-colors duration-150 ease-out placeholder:text-ink-faint hover:border-rule-strong focus:outline-none ${
          invalid ? "border-maroon" : "border-rule focus:border-maroon"
        }`}
      />
    </div>
  );
}
